        sum: Optional['types.ShotSumAggregateInput'] = None,
        min: Optional['types.ShotMinAggregateInput'] = None,
        max: Optional['types.ShotMaxAggregateInput'] = None,
        having: Optional['types.ShotScalarWhereWithAggregatesInput'] = None,
        count: Optional[Union[bool, 'types.ShotCountAggregateInput']] = None,
        order: Optional[Union[Mapping['types.ShotScalarFieldKeys', 'types.SortOrder'], List[Mapping['types.ShotScalarFieldKeys', 'types.SortOrder']]]] = None,
